150:         Qualification q = Qualification.builder()
151:                 .certificateNumber(certNum)
152:                 .studentFullName(studentName)
153:                 .studentIdNumber(studentId)
154:                 .awardTitle(awardTitle)
155:                 .majorSpecialization(specialization)
156:                 .classification(classification)
157:                 .awardDate(awardDate)
158:                 .institution(institution)
159:                 .status(status)
