        createSeedQualification(
                "QVS-2022-DIP-1109",
                "Marcus Vance",
                "STU-772911",
                "Diploma in Enterprise Systems Administration",
                "Infrastructure Management",
                "Upper Second Class",
                LocalDate.of(2022, 6, 30),
                inst2,
                QualificationStatus.REVOKED,
                "Issued in error - Academic misconduct disciplinary ruling"
        );
    }

